mapper.select:
select cc.`user_id`,cc.`user_name`, count(DISTINCT if((cc.`start_work_clock_time` is not null or cc.`end_work_clock_time` is not null) and (cc.`start_trigger` != 'LEAVE' or cc.`end_Trigger` != 'LEAVE' or (cc.`start_trigger` is null or cc.`end_trigger` is null)),cc.`clock_date`,null)) as ` realWorkDays`, sum(if(cc.`start_work_clock_status` = 'EXP_NOCARD' and cc.`classes_clock_status` != 'EXP_SKIP_WORK',1,0)) as `noClockStartNum`, sum(if(cc.`end_work_clock_status` = 'EXP_NOCARD' and cc.`classes_clock_status` != 'EXP_SKIP_WORK',1,0)) as `noClockEndNum`, sum(if(cc.`start_trigger` = 'REPAIR_CLOCK', 1,0)) as `start_repair_Clock_Num`, sum(if(cc.`end_trigger` = 'REPAIR_CLOCK', 1,0)) as `end_repair_Clock_Num`, sum(if(cc.`start_work_clock_status` = 'EXP_LATE',1,0)) as `lateNum`, sum(if(cc.`start_work_clock_status` = 'EXP_LATE' and timestampdiff(MINUTE,cc.`start_real_time`,cc.`start_work_clock_time`) > 0,timestampdiff(MINUTE,cc.`start_real_time`,cc.`start_work_clock_time`),0)) as `lateTotalTime`, sum(if(cc.`end_work_clock_status` = 'EXP_LEAVE_EARLY',1,0)) as `earlyNum`, sum(if(cc.`end_work_clock_status` = 'EXP_LEAVE_EARLY' and timestampdiff(MINUTE,cc.`end_work_clock_time`,cc.`end_real_time`) > 0,timestampdiff(MINUTE,cc.`end_work_clock_time`,cc.`end_real_time`),0)) as `earlyTotalTime`, sum(if(cc.`classes_clock_status` = 'EXP_SKIP_WORK',1,0)) as `skipWorkNum` from `classes_clock` cc where cc.`deleted` = 0 and cc.`tenant` = #{param.tenant}
and cc.`user_id` = #{param.userId}
and cc.`user_id` in
#{id}
and cc.`start_real_time` >= #{param.period.begin}
and cc.`start_real_time` < #{param.period.end}
GROUP BY cc.`user_id`

select aw.staff_id ,aw.staff_name , count( distinct aw.`date`) as arrange_Work_Days , count(DISTINCT if((cc.`start_work_clock_time` is not null or cc.`end_work_clock_time` is not null) and (cc.`start_trigger` != 'LEAVE' or cc.`end_Trigger` != 'LEAVE' or (cc.`start_trigger` is null or cc.`end_trigger` is null)),cc.`clock_date`,null)) as `real_Work_Days` , sum(if(cc.`start_work_clock_status` = 'EXP_NOCARD',1,0)) /count(distinct aw.`date`) as `no_clock_start_num` , sum(if(cc.`end_work_clock_status` = 'EXP_NOCARD',1,0)) /count(distinct aw.`date`) as `no_Clock_End_Num` , sum(if(cc.`start_trigger` = 'REPAIR_CLOCK', 1,0)) /count(distinct aw.`date`) as `start_repair_Clock_Num` , sum(if(cc.`end_trigger` = 'REPAIR_CLOCK', 1,0)) /count(distinct aw.`date`) as `end_repair_Clock_Num` , sum(if(cc.`start_work_clock_status` = 'EXP_LATE',1,0)) /count(distinct aw.`date`) as `late_Num` , sum(if(cc.`start_work_clock_status` = 'EXP_LATE' and timestampdiff(MINUTE,cc.`start_real_time`,cc.`start_work_clock_time`) > 0,timestampdiff(MINUTE,cc.`start_real_time`,cc.`start_work_clock_time`),0)) /count(distinct aw.`date`) as `late_Total_Time` , sum(if(cc.`end_work_clock_status` = 'EXP_LEAVE_EARLY',1,0)) /count(distinct aw.`date`) as `early_Num` , sum(if(cc.`end_work_clock_status` = 'EXP_LEAVE_EARLY' and timestampdiff(MINUTE,cc.`end_work_clock_time`,cc.`end_real_time`) > 0,timestampdiff(MINUTE,cc.`end_work_clock_time`,cc.`end_real_time`),0)) /count(distinct aw.`date`) as `early_Total_Time` , sum(if(cc.`classes_clock_status` = 'EXP_SKIP_WORK',1,0)) /count(distinct aw.`date`) as `skip_Work_Num` from `arrange_work` aw left join `classes_clock` cc on(cc.`user_id` = aw.`staff_id`
and cc.`clock_date` >= #{param.period.begin}
and cc.`clock_date` < #{param.period.end}
)
aw.`arrange_work_classes_ids` != ''
and aw.`staff_id` = #{param.userId}
and aw.`date` >= #{param.period.begin}
and aw.`date` < #{param.period.end}
#{staffId}
group by aw.`staff_id` ,aw.`staff_name`

select * from `attendance_summary_statistics`


        and `staff_id` = #{param.userId}


       and `aw_time` >= #{param.period.begin} and `owd_time` >= #{param.period.begin} and `lps_time` >= #{param.period.begin} and `hdd_time` >= #{param.period.begin}


        and `aw_time` < #{param.period.end} and `owd_time` < #{param.period.end} and `lps_time` < #{param.period.end} and `hdd_time` < #{param.period.end}



            #{staffId}

SELECT a.`user_id`,a.`tenant`,a.`user_dept_id`
FROM `classes_clock` a
INNER JOIN `arrange_work_classes` b ON a.`arrange_classes_id` = b.`id`
where a.`clock_date` <= #{endDate}
  and a.`clock_date` >= #{startDate}
group by a.`user_id`
